INSERT INTO `famous_people_cards` (`id`, `bridge`, `person`, `dynasty`, `poem`, `info`, `img`, `url`, `create_time`) VALUES (1, '赵州桥', '李春', '隋朝', '制造奇巧，为世所希', '李春，隋朝著名工匠，赵州桥设计建造者。赵州桥建于隋朝大业年间 (公元 605-618 年),是世界上现存最古老、跨度最大的单孔敞肩石拱桥，距今已有 1400 多年历史。', 'zhaozhouqiao.png', 'https://baike.baidu.com/item/李春/107418', '2026-04-28 15:37:10');
INSERT INTO `famous_people_cards` (`id`, `bridge`, `person`, `dynasty`, `poem`, `info`, `img`, `url`, `create_time`) VALUES (2, '洛阳桥', '蔡襄', '宋朝', '洛阳桥下水连天，此地曾经系客船', '蔡襄 (1012-1067),字君谟，北宋著名书法家、政治家。皇祐五年 (1053 年) 主持建造洛阳桥，首创\"筏形基础\"和\"种蛎固基\"技术，是中国桥梁史上的重大创新。', 'luoyangqiao.jpg', 'https://baike.baidu.com/item/蔡襄/27506', '2026-04-28 15:37:10');
INSERT INTO `famous_people_cards` (`id`, `bridge`, `person`, `dynasty`, `poem`, `info`, `img`, `url`, `create_time`) VALUES (3, '卢沟桥', '茅以升', '现代', '卢沟晓月照千古，桥梁精神励后人', '茅以升 (1896-1989),字唐臣，江苏镇江人，中国现代桥梁之父。曾深入研究卢沟桥结构特点，为中国桥梁事业发展作出卓越贡献。', 'lugouqiao.jpg', 'https://baike.baidu.com/item/茅以升/105548', '2026-04-28 15:37:10');
INSERT INTO `famous_people_cards` (`id`, `bridge`, `person`, `dynasty`, `poem`, `info`, `img`, `url`, `create_time`) VALUES (4, '广济桥', '苏轼', '宋代', '广济桥横江面，十八梭船廿四洲', '苏轼 (1037-1101),字子瞻，号东坡居士。虽未直接参与广济桥建造，但其诗文广为传颂，使广济桥名扬天下。广济桥始建于南宋乾道七年 (1171 年)。', 'guangjiqiao.jpg', 'https://baike.baidu.com/item/苏轼/3975', '2026-04-28 15:37:10');
INSERT INTO `famous_people_cards` (`id`, `bridge`, `person`, `dynasty`, `poem`, `info`, `img`, `url`, `create_time`) VALUES (5, '宝带桥', '范仲淹', '唐代', '君到姑苏见，人家尽枕河', '范仲淹 (989-1052),字希文，北宋政治家、文学家。宝带桥始建于唐元和十一年 (816 年),宋代多次修缮。宝带桥是中国现存最长的多孔古石桥。', 'baodaiqiao.jpg', 'https://baike.baidu.com/item/范仲淹/16849', '2026-04-28 15:37:10');
INSERT INTO `famous_people_cards` (`id`, `bridge`, `person`, `dynasty`, `poem`, `info`, `img`, `url`, `create_time`) VALUES (6, '安平桥', '黄守恭', '宋代', '天下无桥长此桥', '黄守恭，宋代著名商人，捐资建造安平桥。安平桥建于南宋绍兴八年 (1138 年),全长 2255 米，是中国现存最长的古代梁式石桥。', 'anpingqiao.jpg', 'https://baike.baidu.com/item/安平桥/10709', '2026-04-28 15:37:10');
INSERT INTO `famous_people_cards` (`id`, `bridge`, `person`, `dynasty`, `poem`, `info`, `img`, `url`, `create_time`) VALUES (7, '枫桥', '张继', '唐代', '月落乌啼霜满天，江枫渔火对愁眠', '张继，字懿孙，唐代诗人。其《枫桥夜泊》一诗使枫桥名扬天下。枫桥位于苏州阊门外，始建于唐代，是江南水乡的标志性古桥。', 'fengqiao.jpg', 'https://baike.baidu.com/item/张继/10566', '2026-04-28 15:37:10');
INSERT INTO `famous_people_cards` (`id`, `bridge`, `person`, `dynasty`, `poem`, `info`, `img`, `url`, `create_time`) VALUES (8, '永通桥', '李春', '隋朝', '赵州桥姊妹桥，千年屹立不倒', '永通桥又称小石桥，位于赵县，与赵州桥相距 2.5 公里。同样由李春设计，建于金代明昌年间 (1190-1195 年),结构精巧，被誉为\"赵州桥的姊妹桥\"。', 'yongtongqiao.jpg', 'https://baike.baidu.com/item/永通桥/10710', '2026-04-28 15:37:10');
